-- Sincronizar secuencias IDENTITY al maximo ID insertado
DO $$
DECLARE
    r RECORD;
    v_max BIGINT;
BEGIN
    FOR r IN (
        SELECT table_name, column_name
        FROM information_schema.columns
        WHERE table_schema = 'public' AND is_identity = 'YES'
    ) LOOP
        EXECUTE format('SELECT COALESCE(MAX(%I), 1) FROM %I', r.column_name, r.table_name) INTO v_max;
        EXECUTE format('SELECT setval(pg_get_serial_sequence(%L, %L), %s, true)', r.table_name, r.column_name, v_max);
    END LOOP;
END $$;
COMMIT;
